// Float scalars
// ---------------------------------------------------------------------------------------

/// The Rust float behind a float scalar class.
trait FloatPrim:
    Copy
    + PartialOrd
    + Add<Output = Self>
    + Sub<Output = Self>
    + Mul<Output = Self>
    + Div<Output = Self>
    + Rem<Output = Self>
    + Neg<Output = Self>
    + Send
    + Sync
    + 'static
{
    const NAME: &'static str;
    const ZERO: Self;
    const ONE: Self;
    fn widen(self) -> f64;
    /// `v` rounded to this type; `None` if a finite `v` overflows it.
    fn narrow(v: f64) -> Option<Self>;
    fn from_i128(v: i128) -> Self;
    /// A Python `int` outside the 64-bit range, correctly rounded.
    fn from_big_pyint(obj: &Bound<'_, PyAny>) -> PyResult<Self>;
    fn floor(self) -> Self;
    fn abs(self) -> Self;
    fn copysign(self, sign: Self) -> Self;
    fn powf(self, exp: Self) -> Self;
    fn is_nan(self) -> bool;
    fn is_infinite(self) -> bool;
    fn repr(self) -> String;
}

impl FloatPrim for f64 {
    const NAME: &'static str = "f64";
    const ZERO: Self = 0.0;
    const ONE: Self = 1.0;
    fn widen(self) -> f64 {
        self
    }
    fn narrow(v: f64) -> Option<Self> {
        Some(v)
    }
    fn from_i128(v: i128) -> Self {
        v as f64
    }
    fn from_big_pyint(obj: &Bound<'_, PyAny>) -> PyResult<Self> {
        // `int.__float__`: correctly rounded, OverflowError beyond the float range.
        obj.extract()
    }
    fn floor(self) -> Self {
        f64::floor(self)
    }
    fn abs(self) -> Self {
        f64::abs(self)
    }
    fn copysign(self, sign: Self) -> Self {
        f64::copysign(self, sign)
    }
    fn powf(self, exp: Self) -> Self {
        f64::powf(self, exp)
    }
    fn is_nan(self) -> bool {
        f64::is_nan(self)
    }
    fn is_infinite(self) -> bool {
        f64::is_infinite(self)
    }
    fn repr(self) -> String {
        pyfmt::float_repr(self)
    }
}

impl FloatPrim for f32 {
    const NAME: &'static str = "f32";
    const ZERO: Self = 0.0;
    const ONE: Self = 1.0;
    fn widen(self) -> f64 {
        f64::from(self)
    }
    fn narrow(v: f64) -> Option<Self> {
        let x = v as f32;
        (!x.is_infinite() || v.is_infinite()).then_some(x)
    }
    fn from_i128(v: i128) -> Self {
        v as f32
    }
    fn from_big_pyint(obj: &Bound<'_, PyAny>) -> PyResult<Self> {
        // Convert from the exact integer (not via f64) to avoid double rounding.
        let x = match obj.extract::<i128>() {
            Ok(v) => v as f32,
            Err(_) => obj.extract::<u128>().map_or(f32::INFINITY, |v| v as f32),
        };
        if x.is_infinite() {
            return Err(PyOverflowError::new_err("int too large to convert to f32"));
        }
        Ok(x)
    }
    fn floor(self) -> Self {
        f32::floor(self)
    }
    fn abs(self) -> Self {
        f32::abs(self)
    }
    fn copysign(self, sign: Self) -> Self {
        f32::copysign(self, sign)
    }
    fn powf(self, exp: Self) -> Self {
        f32::powf(self, exp)
    }
    fn is_nan(self) -> bool {
        f32::is_nan(self)
    }
    fn is_infinite(self) -> bool {
        f32::is_infinite(self)
    }
    fn repr(self) -> String {
        pyfmt::f32_repr(self)
    }
}

/// A float scalar class.
trait FloatScalar: pyo3::PyClass {
    type Prim: FloatPrim;
    fn exact(obj: &Bound<'_, PyAny>) -> Option<Self::Prim>;
    fn object(py: Python<'_>, v: Self::Prim) -> PyResult<Py<PyAny>>;
}

fn float_narrow<F: FloatPrim>(v: f64) -> PyResult<F> {
    F::narrow(v)
        .ok_or_else(|| PyOverflowError::new_err(format!("{} is out of range for {}", pyfmt::float_repr(v), F::NAME)))
}

fn float_from_pyint<F: FloatPrim>(obj: &Bound<'_, PyAny>) -> PyResult<F> {
    match PyIntVal::of(obj)? {
        PyIntVal::Small(v) => Ok(F::from_i128(v)),
        _ => F::from_big_pyint(obj),
    }
}

/// An operator operand: the same class, a Python `float` or `int`. `None` means
/// `NotImplemented`.
#[inline]
fn float_operand<C: FloatScalar>(other: &Bound<'_, PyAny>) -> PyResult<Option<C::Prim>> {
    if let Some(v) = C::exact(other) {
        return Ok(Some(v));
    }
    if let Ok(f) = other.cast::<PyFloat>() {
        return float_narrow(f.value()).map(Some);
    }
    if other.is_instance_of::<PyInt>() {
        return float_from_pyint(other).map(Some);
    }
    Ok(None)
}

fn float_arg<C: FloatScalar>(other: &Bound<'_, PyAny>) -> PyResult<C::Prim> {
    float_operand::<C>(other)?.ok_or_else(|| {
        PyTypeError::new_err(format!("expected {}, float or int, got '{}'", C::Prim::NAME, type_name(other)))
    })
}

/// Python's float `%` (`float_rem`): the result takes the divisor's sign.
fn float_mod<F: FloatPrim>(a: F, b: F) -> F {
    let m = a % b;
    if m != F::ZERO { if (b < F::ZERO) != (m < F::ZERO) { m + b } else { m } } else { F::ZERO.copysign(b) }
}

/// Python's float `divmod` (`_float_div_mod`), in the type's own precision.
fn float_divmod<F: FloatPrim>(a: F, b: F) -> (F, F) {
    let mut m = a % b;
    let mut div = (a - m) / b;
    if m != F::ZERO {
        if (b < F::ZERO) != (m < F::ZERO) {
            m = m + b;
            div = div - F::ONE;
        }
    } else {
        m = F::ZERO.copysign(b);
    }
    let floordiv = if div != F::ZERO {
        let f = div.floor();
        // Snap to the nearest integer: `div` is within an ulp of one.
        if div - f > F::ONE / (F::ONE + F::ONE) { f + F::ONE } else { f }
    } else {
        F::ZERO.copysign(a / b)
    };
    (floordiv, m)
}

fn is_odd_integer<F: FloatPrim>(x: F) -> bool {
    let two = F::ONE + F::ONE;
    x.floor() == x && x % two != F::ZERO
}

/// Python's float `**` (`float_pow`) in the type's own precision. A negative base with a
/// non-integral exponent (a `complex` in Python) raises `ValueError`.
fn float_pow<F: FloatPrim>(v: F, w: F) -> PyResult<F> {
    if w == F::ZERO {
        return Ok(F::ONE);
    }
    if v.is_nan() {
        return Ok(v);
    }
    if w.is_nan() {
        return Ok(if v == F::ONE { F::ONE } else { w });
    }
    if w.is_infinite() {
        let v = v.abs();
        return Ok(if v == F::ONE {
            F::ONE
        } else if (w > F::ZERO) == (v > F::ONE) {
            w.abs()
        } else {
            F::ZERO
        });
    }
    if v.is_infinite() {
        let odd = is_odd_integer(w);
        return Ok(if w > F::ZERO {
            if odd { v } else { v.abs() }
        } else if odd {
            F::ZERO.copysign(v)
        } else {
            F::ZERO
        });
    }
    if v == F::ZERO {
        if w < F::ZERO {
            return Err(PyZeroDivisionError::new_err("zero to a negative power"));
        }
        return Ok(if is_odd_integer(w) { v } else { F::ZERO });
    }
    let (mut base, mut negate) = (v, false);
    if v < F::ZERO {
        if w.floor() != w {
            return Err(PyValueError::new_err("negative number cannot be raised to a fractional power"));
        }
        base = -v;
        negate = is_odd_integer(w);
    }
    if base == F::ONE {
        return Ok(if negate { -F::ONE } else { F::ONE });
    }
    let r = base.powf(w);
    if r.is_infinite() {
        return Err(PyOverflowError::new_err((34, "Numerical result out of range")));
    }
    Ok(if negate { -r } else { r })
}

fn float_binop<C: FloatScalar>(lhs: C::Prim, other: &Bound<'_, PyAny>, reflected: bool, op: Op) -> PyResult<Py<PyAny>> {
    let py = other.py();
    let Some(rhs) = float_operand::<C>(other)? else {
        return Ok(py.NotImplemented());
    };
    let (a, b) = if reflected { (rhs, lhs) } else { (lhs, rhs) };
    let v = match op {
        Op::Add => a + b,
        Op::Sub => a - b,
        Op::Mul => a * b,
        Op::FloorDiv | Op::Mod if b == C::Prim::ZERO => return Err(zero_division()),
        Op::FloorDiv => float_divmod(a, b).0,
        Op::Mod => float_mod(a, b),
        Op::And | Op::Or | Op::Xor => return Ok(py.NotImplemented()),
    };
    C::object(py, v)
}

fn float_truediv<C: FloatScalar>(lhs: C::Prim, other: &Bound<'_, PyAny>, reflected: bool) -> PyResult<Py<PyAny>> {
    let py = other.py();
    let Some(rhs) = float_operand::<C>(other)? else {
        return Ok(py.NotImplemented());
    };
    let (a, b) = if reflected { (rhs, lhs) } else { (lhs, rhs) };
    if b == C::Prim::ZERO {
        return Err(zero_division());
    }
    C::object(py, a / b)
}

fn float_divmod_op<C: FloatScalar>(lhs: C::Prim, other: &Bound<'_, PyAny>, reflected: bool) -> PyResult<Py<PyAny>> {
    let py = other.py();
    let Some(rhs) = float_operand::<C>(other)? else {
        return Ok(py.NotImplemented());
    };
    let (a, b) = if reflected { (rhs, lhs) } else { (lhs, rhs) };
    if b == C::Prim::ZERO {
        return Err(zero_division());
    }
    let (q, m) = float_divmod(a, b);
    (C::object(py, q)?, C::object(py, m)?).into_py_any(py)
}

fn float_pow_op<C: FloatScalar>(
    lhs: C::Prim,
    other: &Bound<'_, PyAny>,
    modulo: Option<&Bound<'_, PyAny>>,
    reflected: bool,
) -> PyResult<Py<PyAny>> {
    let py = other.py();
    let Some(rhs) = float_operand::<C>(other)? else {
        return Ok(py.NotImplemented());
    };
    if modulo.is_some() {
        return Err(PyTypeError::new_err("pow() 3rd argument not allowed unless all arguments are integers"));
    }
    let (a, b) = if reflected { (rhs, lhs) } else { (lhs, rhs) };
    C::object(py, float_pow(a, b)?)
}

fn float_richcmp<C: FloatScalar>(lhs: C::Prim, other: &Bound<'_, PyAny>, op: CompareOp) -> PyResult<Py<PyAny>> {
    let py = other.py();
    let x = lhs.widen();
    let ord = if let Some(v) = C::exact(other) {
        lhs.partial_cmp(&v)
    } else if let Ok(f) = other.cast::<PyFloat>() {
        x.partial_cmp(&f.value())
    } else if other.is_instance_of::<PyInt>() {
        match PyIntVal::of(other)? {
            PyIntVal::Small(v) => cmp_i128_f64(v, x).map(Ordering::reverse),
            // Python's float/int comparison is exact for ints of any size.
            _ => return Ok(PyFloat::new(py, x).rich_compare(other, op)?.unbind()),
        }
    } else {
        return Ok(py.NotImplemented());
    };
    bool_obj(py, compare(ord, op))
}

/// Constructor argument of a float class: a real number (`float`, `int`, scalar, or an
/// object with `__float__`/`__index__`). Strings are rejected.
fn float_new<C: FloatScalar>(args: &Bound<'_, PyTuple>) -> PyResult<C::Prim> {
    let obj = match args.len() {
        0 => return Ok(C::Prim::ZERO),
        1 => args.get_item(0)?,
        n => {
            return Err(PyTypeError::new_err(format!("{}() takes at most 1 argument ({n} given)", C::Prim::NAME)));
        }
    };
    if let Some(v) = float_operand::<C>(&obj)? {
        return Ok(v);
    }
    match scalar_value(&obj) {
        Some(Value::F32(v)) => float_narrow(f64::from(v)),
        Some(Value::F64(v)) => float_narrow(v),
        Some(v) => match int_value(&v) {
            Some(i) => Ok(C::Prim::from_i128(i)),
            None => Err(PyTypeError::new_err("unsupported scalar")),
        },
        // `float(x)` semantics minus string parsing: `__float__`, then `__index__`.
        None => float_narrow(obj.extract::<f64>()?),
    }
}

fn int_value(v: &Value) -> Option<i128> {
    Some(match *v {
        Value::I8(x) => x.into(),
        Value::I16(x) => x.into(),
        Value::I32(x) => x.into(),
        Value::I64(x) => x.into(),
        Value::U8(x) => x.into(),
        Value::U16(x) => x.into(),
        Value::U32(x) => x.into(),
        Value::U64(x) => x.into(),
        _ => return None,
    })
}

/// Whether a format spec uses the default ("repr") presentation: no precision, no type.
fn is_repr_spec(spec: &str) -> bool {
    let mut chars = spec.chars();
    let rest = match (chars.next(), chars.next()) {
        (Some(_), Some(a)) if "<>=^".contains(a) => chars.as_str(),
        (Some(a), _) if "<>=^".contains(a) => &spec[a.len_utf8()..],
        _ => spec,
    };
    !rest.contains('.') && !rest.ends_with(|c| "eEfFgGn%".contains(c))
}

macro_rules! float_scalar {
    ($Name:ident, $t:ident, $pyname:tt, $doc:tt) => {
        #[doc = $doc]
        #[pyclass(frozen, immutable_type, module = "rustique", name = $pyname)]
        pub struct $Name(pub $t);

        impl FloatScalar for $Name {
            type Prim = $t;
            #[inline]
            fn exact(obj: &Bound<'_, PyAny>) -> Option<$t> {
                obj.cast_exact::<$Name>().ok().map(|s| s.get().0)
            }
            #[inline]
            fn object(py: Python<'_>, v: $t) -> PyResult<Py<PyAny>> {
                Ok(Bound::new(py, $Name(v))?.into_any().unbind())
            }
        }

        #[pymethods]
        impl $Name {
            #[new]
            #[pyo3(signature = (*args))]
            fn __new__(args: &Bound<'_, PyTuple>) -> PyResult<Self> {
                float_new::<Self>(args).map(Self)
            }

            #[classattr]
            #[pyo3(name = "MIN")]
            fn min_value() -> Self {
                Self($t::MIN)
            }
            #[classattr]
            #[pyo3(name = "MAX")]
            fn max_value() -> Self {
                Self($t::MAX)
            }
            #[classattr]
            #[pyo3(name = "MIN_POSITIVE")]
            fn min_positive() -> Self {
                Self($t::MIN_POSITIVE)
            }
            #[classattr]
            #[pyo3(name = "EPSILON")]
            fn epsilon() -> Self {
                Self($t::EPSILON)
            }
            #[classattr]
            #[pyo3(name = "INFINITY")]
            fn infinity() -> Self {
                Self($t::INFINITY)
            }
            #[classattr]
            #[pyo3(name = "NEG_INFINITY")]
            fn neg_infinity() -> Self {
                Self($t::NEG_INFINITY)
            }
            #[classattr]
            #[pyo3(name = "NAN")]
            fn nan() -> Self {
                Self($t::NAN)
            }
            #[classattr]
            fn __match_args__() -> (&'static str,) {
                ("value",)
            }

            /// The value as a Python `float` (exact).
            #[getter]
            fn value(&self) -> f64 {
                FloatPrim::widen(self.0)
            }

            fn __repr__(&self) -> String {
                format!(concat!(stringify!($t), "({})"), FloatPrim::repr(self.0))
            }

            fn __str__(&self) -> String {
                FloatPrim::repr(self.0)
            }

            fn __format__<'py>(&self, py: Python<'py>, spec: &str) -> PyResult<Bound<'py, PyAny>> {
                let repr = FloatPrim::repr(self.0);
                if spec.is_empty() {
                    return Ok(PyString::new(py, &repr).into_any());
                }
                // The shortest digits of this type, not of the widened f64, unless the spec
                // asks for a precision or presentation type.
                let x = if is_repr_spec(spec) {
                    repr.parse::<f64>().unwrap_or(FloatPrim::widen(self.0))
                } else {
                    FloatPrim::widen(self.0)
                };
                PyFloat::new(py, x).call_method1(intern!(py, "__format__"), (spec,))
            }

            fn __hash__(slf: &Bound<'_, Self>) -> isize {
                // NaN hashes by identity, like `float`.
                pyhash::hash_f64(FloatPrim::widen(slf.get().0))
                    .unwrap_or_else(|| pyhash::hash_pointer(slf.as_ptr() as usize))
            }

            fn __richcmp__(&self, other: &Bound<'_, PyAny>, op: CompareOp) -> PyResult<Py<PyAny>> {
                float_richcmp::<Self>(self.0, other, op)
            }

            fn __bool__(&self) -> bool {
                self.0 != 0.0
            }

            fn __int__<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
                PyFloat::new(py, FloatPrim::widen(self.0)).call_method0(intern!(py, "__int__"))
            }

            fn __float__(&self) -> f64 {
                FloatPrim::widen(self.0)
            }

            fn __reduce__<'py>(slf: &Bound<'py, Self>) -> (Bound<'py, PyType>, (f64,)) {
                (slf.get_type(), (FloatPrim::widen(slf.get().0),))
            }

            fn __copy__<'py>(slf: &Bound<'py, Self>) -> Bound<'py, Self> {
                slf.clone()
            }

            fn __deepcopy__<'py>(slf: &Bound<'py, Self>, _memo: &Bound<'py, PyAny>) -> Bound<'py, Self> {
                slf.clone()
            }

            fn __trunc__<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
                PyFloat::new(py, FloatPrim::widen(self.0)).call_method0(intern!(py, "__trunc__"))
            }

            fn __floor__<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
                PyFloat::new(py, FloatPrim::widen(self.0)).call_method0(intern!(py, "__floor__"))
            }

            fn __ceil__<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
                PyFloat::new(py, FloatPrim::widen(self.0)).call_method0(intern!(py, "__ceil__"))
            }

            /// `round(x)` is a Python `int`; `round(x, n)` stays in the type.
            #[pyo3(signature = (ndigits=None))]
            fn __round__(&self, py: Python<'_>, ndigits: Option<&Bound<'_, PyAny>>) -> PyResult<Py<PyAny>> {
                let x = PyFloat::new(py, FloatPrim::widen(self.0));
                match ndigits {
                    None => Ok(x.call_method0(intern!(py, "__round__"))?.unbind()),
                    Some(n) => {
                        let r: f64 = x.call_method1(intern!(py, "__round__"), (n,))?.extract()?;
                        Self::object(py, float_narrow(r)?)
                    }
                }
            }

            fn __add__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_binop::<Self>(self.0, other, false, Op::Add)
            }
            fn __radd__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_binop::<Self>(self.0, other, true, Op::Add)
            }
            fn __sub__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_binop::<Self>(self.0, other, false, Op::Sub)
            }
            fn __rsub__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_binop::<Self>(self.0, other, true, Op::Sub)
            }
            fn __mul__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_binop::<Self>(self.0, other, false, Op::Mul)
            }
            fn __rmul__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_binop::<Self>(self.0, other, true, Op::Mul)
            }
            fn __floordiv__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_binop::<Self>(self.0, other, false, Op::FloorDiv)
            }
            fn __rfloordiv__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_binop::<Self>(self.0, other, true, Op::FloorDiv)
            }
            fn __mod__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_binop::<Self>(self.0, other, false, Op::Mod)
            }
            fn __rmod__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_binop::<Self>(self.0, other, true, Op::Mod)
            }
            fn __truediv__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_truediv::<Self>(self.0, other, false)
            }
            fn __rtruediv__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_truediv::<Self>(self.0, other, true)
            }
            fn __divmod__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_divmod_op::<Self>(self.0, other, false)
            }
            fn __rdivmod__(&self, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
                float_divmod_op::<Self>(self.0, other, true)
            }
            fn __pow__(&self, other: &Bound<'_, PyAny>, modulo: Option<&Bound<'_, PyAny>>) -> PyResult<Py<PyAny>> {
                float_pow_op::<Self>(self.0, other, modulo, false)
            }
            fn __rpow__(&self, other: &Bound<'_, PyAny>, modulo: Option<&Bound<'_, PyAny>>) -> PyResult<Py<PyAny>> {
                float_pow_op::<Self>(self.0, other, modulo, true)
            }

            fn __neg__(&self) -> Self {
                Self(-self.0)
            }
            fn __pos__<'py>(slf: &Bound<'py, Self>) -> Bound<'py, Self> {
                slf.clone()
            }
            fn __abs__(&self) -> Self {
                Self(self.0.abs())
            }

            // Rust's float methods, computed in this type's precision.

            fn is_nan(&self) -> bool {
                self.0.is_nan()
            }
            fn is_finite(&self) -> bool {
                self.0.is_finite()
            }
            fn is_infinite(&self) -> bool {
                self.0.is_infinite()
            }
            fn is_normal(&self) -> bool {
                self.0.is_normal()
            }
            fn is_sign_positive(&self) -> bool {
                self.0.is_sign_positive()
            }
            fn is_sign_negative(&self) -> bool {
                self.0.is_sign_negative()
            }
            fn sqrt(&self) -> Self {
                Self(self.0.sqrt())
            }
            fn abs(&self) -> Self {
                Self(self.0.abs())
            }
            fn floor(&self) -> Self {
                Self(self.0.floor())
            }
            fn ceil(&self) -> Self {
                Self(self.0.ceil())
            }
            fn trunc(&self) -> Self {
                Self(self.0.trunc())
            }
            fn fract(&self) -> Self {
                Self(self.0.fract())
            }
            #[pyo3(signature = (sign, /))]
            fn copysign(&self, sign: &Bound<'_, PyAny>) -> PyResult<Self> {
                Ok(Self(self.0.copysign(float_arg::<Self>(sign)?)))
            }
            #[pyo3(signature = (exp, /))]
            fn powf(&self, exp: &Bound<'_, PyAny>) -> PyResult<Self> {
                Ok(Self(self.0.powf(float_arg::<Self>(exp)?)))
            }
            #[pyo3(signature = (exp, /))]
            fn powi(&self, exp: i32) -> Self {
                Self(self.0.powi(exp))
            }
            #[pyo3(signature = (other, /))]
            fn min(&self, other: &Bound<'_, PyAny>) -> PyResult<Self> {
                Ok(Self(self.0.min(float_arg::<Self>(other)?)))
            }
            #[pyo3(signature = (other, /))]
            fn max(&self, other: &Bound<'_, PyAny>) -> PyResult<Self> {
                Ok(Self(self.0.max(float_arg::<Self>(other)?)))
            }
            /// The IEEE 754 bit pattern as an unsigned `int`.
            fn to_bits(&self) -> u64 {
                self.0.to_bits().into()
            }
            #[classmethod]
            #[pyo3(signature = (bits, /))]
            fn from_bits(_cls: &Bound<'_, PyType>, bits: &Bound<'_, PyAny>) -> PyResult<Self> {
                let bits = int_from_pyint(bits)?;
                Ok(Self($t::from_bits(bits)))
            }
            fn to_be_bytes<'py>(&self, py: Python<'py>) -> Bound<'py, PyBytes> {
                PyBytes::new(py, &self.0.to_be_bytes())
            }
            fn to_le_bytes<'py>(&self, py: Python<'py>) -> Bound<'py, PyBytes> {
                PyBytes::new(py, &self.0.to_le_bytes())
            }
            fn to_ne_bytes<'py>(&self, py: Python<'py>) -> Bound<'py, PyBytes> {
                PyBytes::new(py, &self.0.to_ne_bytes())
            }
            #[classmethod]
            #[pyo3(signature = (bytes, /))]
            fn from_be_bytes(_cls: &Bound<'_, PyType>, bytes: &Bound<'_, PyAny>) -> PyResult<Self> {
                Ok(Self($t::from_be_bytes(fixed_bytes(stringify!($t), "from_be_bytes", bytes)?)))
            }
            #[classmethod]
            #[pyo3(signature = (bytes, /))]
            fn from_le_bytes(_cls: &Bound<'_, PyType>, bytes: &Bound<'_, PyAny>) -> PyResult<Self> {
                Ok(Self($t::from_le_bytes(fixed_bytes(stringify!($t), "from_le_bytes", bytes)?)))
            }
            #[classmethod]
            #[pyo3(signature = (bytes, /))]
            fn from_ne_bytes(_cls: &Bound<'_, PyType>, bytes: &Bound<'_, PyAny>) -> PyResult<Self> {
                Ok(Self($t::from_ne_bytes(fixed_bytes(stringify!($t), "from_ne_bytes", bytes)?)))
            }
        }
    };
}

float_scalar!(F32, f32, "f32", "32-bit IEEE 754 float; arithmetic rounds to single precision.");
